        if not line.strip():
            continue
        if line.startswith("#"):
            yield "comment", line
            continue
        if delim == ",":
            while line.count('"') % 2 and i < len(lines):
                line += "\n" + lines[i]
                i += 1
            fields = next(csv.reader([line], delimiter=",", quotechar='"'))
        else:
            fields = line.split(delim)
        yield "row", fields


def parse_delimited(depot, text):
    delim = DELIM[depot]
    cols = COLUMNS[depot]
    seq = None
    dirs = {}
    header = None
    out = []
    for kind, val in csv_rows(text, delim):
        if kind == "comment":
            m = re.match(r"#\s*([^:=]+?)\s*:\s*(.*)$", val)
            if m:
                dirs[m[1].lower()] = m[2].strip()
                if m[1].lower() == "seq" and seq is None:
                    seq = int(m[2])
            else:
                m = re.search(r"seq\s*=\s*(\d+)", val)
                if m and seq is None:
                    seq = int(m[1])
            continue
        f = val
        names = [x.strip().lower() for x in f]
        if all(n in cols for n in names) and len(set(names)) == len(names):
            header = names
            continue
        if header is None:
            continue
        row_unit = None
        if len(f) == len(header) + 1 and f[-1].strip().lower() in FACTORS:
            row_unit = f[-1].strip().lower()
            f = f[:-1]
        f = f + [""] * (len(header) - len(f))
        r = dict(zip(header, f))
        idf = r.get("id", r.get("ref", ""))
        num = parse_id(idf)
        if num is None:
            continue
        typ = TYPES[(r.get("type") or r.get("kind") or r.get("typ") or r.get("t")
                     or r.get("rec") or "").strip().lower()]
        if typ == "void":
            out.append(rec("void", num, None, None, None))
            continue
        dform = dirs.get("dates") or dirs.get("date format") or BASE_DATE[depot]
        if depot == "west":
            dform = "dd.mm.yyyy"
        d = parse_date(r.get("shipped") or r.get("date"), dform)
        # weight
        wfield = next(c for c in ("gross", "gross_kg", "weight") if c in r)
        num_s, unit = split_weight(r[wfield])
        if unit is None and wfield.endswith("_kg"):
            unit = "kg"
        if unit is None:
            unit = row_unit
        if unit is None:
            u = dirs.get("unit") or dirs.get("weight unit")
            if u:
                unit = u.split()[0].lower()
        if unit is None:
            unit = "kg"
        cd = depot == "west" or any("decimal comma" in v for k, v in dirs.items()
                                    if "unit" in k)
        kg = parse_number(num_s, cd) * FACTORS[unit]
        out.append(rec(typ, num, norm_status(r.get("status") or r.get("state")), d, kg))
    return seq, out


# --------------------------------------------------------------- fixed width
LAYOUTS = {
    "FW1": (42, dict(id=(0, 9), type=(9, 10), ship=(10, 17), w=(17, 25), st=(25, 26)),
            "yyyyddd", Fraction(1, 1000)),
    "FW2": (43, dict(type=(0, 1), id=(1, 10), ship=(10, 18), w=(18, 26), st=(26, 27)),
            "yyyymmdd", Fraction(1, 100)),
    "FW3": (41, dict(id=(0, 9), ship=(9, 16), type=(16, 17), w=(17, 24), st=(24, 25)),
            "yyyyddd", FACTORS["lb"] / 10),
}


def parse_fixed(text):
    seq = None
    layout = None
    out = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if not line.strip() or "\f" in line or line.lstrip().startswith("SOUTH"):
            continue
        if line.startswith("#"):
            m = re.match(r"#LAYOUT\s+(\w+)", line)
            if m:
                layout = m[1]
            m = re.match(r"#SEQ\s+(\d+)", line)
            if m and seq is None:
                seq = int(m[1])
            continue
        by_len = [k for k, v in LAYOUTS.items() if v[0] == len(line)]
        if by_len:
            lay = by_len[0]
        else:
            lay = layout
            if lay is None:
                continue
            line = line.ljust(LAYOUTS[lay][0])
        _, pos, dform, scale = LAYOUTS[lay]
        g = {k: line[a:b] for k, (a, b) in pos.items()}
        num = parse_id(g["id"])
        if num is None:
            continue
        typ = TYPES[g["type"].strip().lower()]
        if typ == "void":
            out.append(rec("void", num, None, None, None))
            continue
        s = g["ship"]
        if dform == "yyyyddd":
            d = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            d = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        out.append(rec(typ, num, CODES[g["st"].strip().upper()], d,
                       int(g["w"]) * scale))
    return seq, out


# ----------------------------------------------------------------------- XML
def parse_xml(raw):
    root = ET.fromstring(raw)
    seq = int(root.get("seq")) if root.get("seq") else None
    runit = (root.get("weight-unit") or "kg").lower()
    out = []
    for el in root.iter("shipment"):
        num = parse_id(el.get("id"))
        if num is None:
            continue
        typ = TYPES[(el.get("type") or "").strip().lower()]
        if typ == "void":
            out.append(rec("void", num, None, None, None))
            continue
        sh = el.get("shipped")
        if sh is None:
            sh = el.findtext("shipped")
        sh = sh.strip()
        d = parse_date(sh, "") if not re.search(r"[T:]", sh) else parse_time(sh)
        w = el.find("weight")
        unit = (w.get("unit") or runit).lower()
        kg = parse_number(w.text, False) * FACTORS[unit]
        out.append(rec(typ, num, norm_status(el.findtext("status")), d, kg))
    return seq, out


# --------------------------------------------------------------------- JSONL
def parse_jsonl(text):
    seq = None
    out = []
    for line in text.split("\n"):
        if not line.strip():
            continue
        v = json.loads(line, parse_float=Decimal, parse_int=Decimal)
        for o in (v if isinstance(v, list) else [v]):
            if not isinstance(o, dict):
                continue
            if "meta" in o:
                if seq is None and o["meta"].get("seq") is not None:
                    seq = int(o["meta"]["seq"])
                continue
            num = parse_id(str(o.get("id")))
            if num is None:
                continue
            typ = TYPES[str(o.get("kind") or "new").lower()]
            if typ == "void":
                out.append(rec("void", num, None, None, None))
                continue
            wk = next(k for k in o if k.startswith("weight_"))
            unit = wk[len("weight_"):].lower()
            kg = Fraction(Decimal(str(o[wk]))) * FACTORS[unit]
            out.append(rec(typ, num, norm_status(o.get("status")),
                           parse_time(o["shipped_at"]), kg))
    return seq, out


def parse_file(depot, path):
    raw = open(path, "rb").read()
    if raw[:2] == b"\x1f\x8b":
        raw = gzip.decompress(raw)
    stripped = raw.lstrip(b"\xef\xbb\xbf\xff\xfe\xfe")
    if depot in DELIM:
        return parse_delimited(depot, read_text(raw))
    if depot == "south":
        return parse_fixed(read_text(raw))
    if depot == "central":
        return parse_xml(raw)
    if depot == "north":
        return parse_jsonl(read_text(raw))
    # unknown depot: sniff
    t = read_text(raw).lstrip()
    if t.startswith("<"):
        return parse_xml(raw)
    if t.startswith("{") or t.startswith("["):
        return parse_jsonl(t)
    raise ValueError("unknown depot " + depot)


def rnd2(x):
    n = (x * 100 + Fraction(1, 2)).__floor__()
    return float(Decimal(n) / 100)


def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-", 1)[0]
        seq, recs = parse_file(depot, p)
        exports.setdefault(depot, []).append((seq if seq is not None else 0, name, recs))
    corrections = resends = 0
    current = {}
    for depot, lst in exports.items():
        cur = {}
        for _, _, recs in sorted(lst, key=lambda x: (x[0], x[1])):
            for r in recs:
                n = r["num"]
                if r["kind"] == "new":
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r["kind"] == "correction":
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
        current[depot] = cur
    rank = {d: i for i, d in enumerate(ORDER)}
    holders = {}
    for depot, cur in current.items():
        for n in cur:
            holders.setdefault(n, []).append(depot)
    handovers = 0
    depots = {d: [0, Fraction(0)] for d in exports}
    months = {}
    for n, ds in holders.items():
        if len(ds) > 1:
            handovers += 1
        d = min(ds, key=lambda x: (rank.get(x, 99), x))
        r = current[d][n]
        if r["status"] not in ("delivered", "delivered_late"):
            continue
        depots[d][0] += 1
        depots[d][1] += r["kg"]
        m = months.setdefault(r["date"].strftime("%Y-%m"), [0, Fraction(0)])
        m[0] += 1
        m[1] += r["kg"]
    result = {
        "depots": {d: {"shipments": v[0], "total_kg": rnd2(v[1])}
                   for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": rnd2(v[1])}
                   for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
